<?php declare(strict_types=1);require_once __DIR__.'/auth.php';if(portal_user()){header('Location: index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){portal_check_csrf();$email=strtolower(trim($_POST['email']??''));$p=$_POST['password']??'';$now=time();if(!isset($_SESSION['portal_login_attempts']))$_SESSION['portal_login_attempts']=[];$_SESSION['portal_login_attempts']=array_values(array_filter($_SESSION['portal_login_attempts'],fn($t)=>$t>$now-900));if(count($_SESSION['portal_login_attempts'])>=8){http_response_code(429);$error='Too many login attempts. Please try again later.';}else{$_SESSION['portal_login_attempts'][]=$now;$q=$db->prepare('SELECT id,password_hash,is_active FROM client_portal_users WHERE email=? LIMIT 1');$q->execute([$email]);$u=$q->fetch();if($u&&$u['is_active']&&password_verify($p,$u['password_hash'])){unset($_SESSION['portal_login_attempts']);portal_login((int)$u['id']);$db->prepare('UPDATE client_portal_users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);header('Location: index.php');exit;}$error='Invalid login details.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Portal Login</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:480px"><div class="card"><div class="card-body p-4"><h1 class="h4 mb-4">Client Portal</h1><?php if($error):?><div class="alert alert-danger"><?=portal_escape($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=portal_escape(portal_csrf())?>"><input class="form-control mb-3" type="email" name="email" placeholder="Email" required autocomplete="username"><input class="form-control mb-3" type="password" name="password" placeholder="Password" required autocomplete="current-password"><button class="btn btn-dark w-100">Sign in</button></form></div></div></main></body></html>